// ============================================================================
// Artificer Infusions picker — a proper checklist instead of a wall of text
// buried in Features. Self-contained: doesn't touch js/app.js. Persists via
// the sheet's existing generic [name]-field save/load, same pattern as
// js/data/summons.js's #activeSummonsField.
// ============================================================================

const INFUSIONS_LIBRARY = [
  { id:'enhancedDefense', name:'Enhanced Defense', text:'+1 AC to a suit of armor, or +1 AC to a shield, while worn/carried.' },
  { id:'enhancedWeapon', name:'Enhanced Weapon', text:'+1 to attack and damage rolls with a nonmagical weapon.' },
  { id:'repeatingShot', name:'Repeating Shot', text:'+1 to attack and damage rolls with a nonmagical ammunition-using weapon; it never needs ammunition when infused.' },
  { id:'resistantArmor', name:'Resistant Armor', text:'While worn, grants resistance to one damage type you choose when you infuse it.' },
  { id:'enhancedArcaneFocus', name:'Enhanced Arcane Focus', text:'+1 to spell attack rolls made with this item as a focus, and it can channel your spells.' },
  { id:'homunculusServant', name:'Homunculus Servant', text:'Infuse a gem, crystal, or metal figurine to create a Tiny construct companion (see the Summons panel).' },
  { id:'bootsWindingPath', name:'Boots of the Winding Path', text:'As a bonus action, teleport to a spot you\'ve previously marked while wearing them.' },
  { id:'replicateMagicItem', name:'Replicate Magic Item', text:'Pick from a DMG list of minor magic items (Bag of Holding, Goggles of Night, Cloak of Elvenkind, etc.) — write which one in the notes.' },
  { id:'mindSharpener', name:'Mind Sharpener', text:'While holding it, gain temporary HP when you start Concentrating, and advantage on Concentration checks while you have any of those temp HP left.' },
  { id:'radiantWeapon', name:'Radiant Weapon', text:'+1 weapon; can flare to shed light and, once per turn on a hit, add 1d4 radiant damage.' },
  { id:'returningWeapon', name:'Returning Weapon', text:'A thrown weapon that flies back to your hand right after it\'s thrown or after missing/hitting.' },
  { id:'armorOfMagicalStrength', name:'Armor of Magical Strength', text:'While worn, store up to 20 temporary HP (as a bonus action reaction to being reduced to 0) — infuse into a suit of armor.' }
];

// level -> known infusions / max simultaneously infused items
const INFUSION_PROGRESSION = [
  { lvl:18, known:12, active:6 },
  { lvl:14, known:10, active:5 },
  { lvl:10, known:8, active:4 },
  { lvl:6, known:6, active:3 },
  { lvl:2, known:4, active:2 }
];

(function(){

  function infusionCaps(){
    const classLevelField = document.querySelector('[name="classLevel"]');
    const text = classLevelField ? classLevelField.value : '';
    const m = text.match(/(\d+)/);
    const level = m ? parseInt(m[1], 10) : 0;
    const isArtificer = /artificer/i.test(text);
    const tier = INFUSION_PROGRESSION.find(t => level >= t.lvl);
    return {
      level, isArtificer,
      known: tier ? tier.known : 0,
      active: tier ? tier.active : 0
    };
  }

  function readKnown(){
    const field = document.getElementById('knownInfusionsField');
    if(!field || !field.value) return [];
    try { const arr = JSON.parse(field.value); return Array.isArray(arr) ? arr : []; } catch(e){ return []; }
  }
  function writeKnown(list){
    const field = document.getElementById('knownInfusionsField');
    if(field) field.value = JSON.stringify(list);
  }

  function renderSummary(){
    const el = document.getElementById('infusionsSummary');
    if(!el) return;
    const caps = infusionCaps();
    const known = readKnown();
    let text;
    if(!caps.isArtificer){
      text = `Class field doesn't say "Artificer" — showing the full reference list with no known-count limit.`;
    } else if(caps.level < 2){
      text = `Infuse Item unlocks at Artificer level 2 — set your level first.`;
    } else {
      text = `Known: ${known.length} / ${caps.known} · Max infused at once: ${caps.active}`;
    }
    el.innerHTML = `<span style="font-size:12px;">${text}</span>`;
  }

  function renderList(){
    const container = document.getElementById('infusionsList');
    if(!container) return;
    const known = readKnown();
    const caps = infusionCaps();
    container.innerHTML = INFUSIONS_LIBRARY.map(inf=>{
      const entry = known.find(k => k.id === inf.id);
      const checked = !!entry;
      return `<div class="infusion-item${checked?' checked':''}" data-id="${inf.id}">
        <div class="if-row">
          <input type="checkbox" class="if-check" ${checked?'checked':''}>
          <div>
            <div class="if-name">${inf.name}</div>
            <div class="if-text">${inf.text}</div>
          </div>
        </div>
        <input type="text" class="if-applied" placeholder="Applied to which item? (optional)" value="${entry && entry.appliedTo ? entry.appliedTo.replace(/"/g,'&quot;') : ''}">
      </div>`;
    }).join('');

    container.querySelectorAll('.infusion-item').forEach(row=>{
      const id = row.dataset.id;
      const checkbox = row.querySelector('.if-check');
      const appliedInput = row.querySelector('.if-applied');
      checkbox.addEventListener('change', ()=>{
        let list = readKnown();
        if(checkbox.checked){
          if(caps.isArtificer && caps.known && list.length >= caps.known){
            checkbox.checked = false;
            if(typeof showToast === 'function') showToast(`You only know ${caps.known} infusions at this level — uncheck one first.`, 'warn');
            return;
          }
          list.push({ id, appliedTo:'' });
        } else {
          list = list.filter(k => k.id !== id);
        }
        writeKnown(list);
        row.classList.toggle('checked', checkbox.checked);
        renderSummary();
      });
      appliedInput.addEventListener('input', ()=>{
        const list = readKnown();
        const entry = list.find(k => k.id === id);
        if(entry){ entry.appliedTo = appliedInput.value; writeKnown(list); }
      });
    });
  }

  function refreshInfusions(){
    renderSummary();
    renderList();
  }

  function openInfusions(){
    refreshInfusions();
    document.getElementById('infusionsOverlay').style.display = 'flex';
  }
  function closeInfusions(){
    document.getElementById('infusionsOverlay').style.display = 'none';
  }

  function init(){
    const openBtn = document.getElementById('btnOpenInfusions');
    const closeBtn = document.getElementById('btnCloseInfusions');
    const overlay = document.getElementById('infusionsOverlay');
    if(openBtn) openBtn.addEventListener('click', openInfusions);
    if(closeBtn) closeBtn.addEventListener('click', closeInfusions);
    if(overlay) overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeInfusions(); });
    document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeInfusions(); });

    // Load File doesn't fire input/change events on restored fields, so
    // re-render shortly after a file is chosen to pick up loaded infusions.
    const fileInput = document.getElementById('fileInput');
    if(fileInput) fileInput.addEventListener('change', ()=> setTimeout(refreshInfusions, 400));
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();

// ============================================================================
// Magical Tinkering (Artificer, level 1) — a proper add/track/end panel
// instead of a single line of feature text. Self-contained: doesn't touch
// js/app.js. Persists via the sheet's existing generic [name]-field
// save/load, same pattern as the Infusions panel above.
// ============================================================================

const TINKER_PROPERTIES = {
  light: { label:'Light', text:'Sheds bright light in a 5-ft. radius and dim light for an additional 5 ft.' },
  message: { label:'Message', text:'Emits a recorded message (up to 6 seconds long), audible up to 10 ft. away, when tapped by a creature.' },
  sound: { label:'Sound or Odor', text:'Continuously emits a chosen odor or nonverbal sound, perceivable up to 10 ft. away.' },
  mark: { label:'Visual Mark', text:'A static visual effect appears on its surface — a picture, up to 25 words of text, lines and shapes, or a mix.' }
};

(function(){

  function tinkerCap(){
    const classLevelField = document.querySelector('[name="classLevel"]');
    const text = classLevelField ? classLevelField.value : '';
    const isArtificer = /artificer/i.test(text);
    let pb = 2;
    try { pb = profBonusFor(text); } catch(e){}
    return { isArtificer, cap: pb };
  }

  function readTinkered(){
    const field = document.getElementById('magicalTinkeringField');
    if(!field || !field.value) return [];
    try { const arr = JSON.parse(field.value); return Array.isArray(arr) ? arr : []; } catch(e){ return []; }
  }
  function writeTinkered(list){
    const field = document.getElementById('magicalTinkeringField');
    if(field) field.value = JSON.stringify(list);
  }

  function renderSummary(){
    const el = document.getElementById('tinkeringSummary');
    if(!el) return;
    const { isArtificer, cap } = tinkerCap();
    const active = readTinkered().length;
    const text = isArtificer
      ? `Active properties: ${active} / ${cap} (your proficiency bonus) — imbuing a new one over the cap isn't allowed by the rules.`
      : `Class field doesn't say "Artificer" — showing this with no cap enforced.`;
    el.innerHTML = `<span style="font-size:12px;">${text}</span>`;
  }

  function renderList(){
    const container = document.getElementById('tinkeringList');
    if(!container) return;
    const list = readTinkered();
    if(!list.length){
      container.innerHTML = `<div class="spellbook-empty">Nothing imbued yet — touch an object above to give it a property.</div>`;
      return;
    }
    container.innerHTML = list.map(item=>{
      const prop = TINKER_PROPERTIES[item.propertyType];
      return `<div class="tinker-item" data-id="${item.id}">
        <div class="ti-head">
          <span class="ti-name">${item.objectName || '(unnamed object)'}</span>
          <span class="ti-type">${prop ? prop.label : item.propertyType}</span>
          <button type="button" class="ti-end">End</button>
        </div>
        <div class="ti-detail">${prop ? prop.text : ''}${item.detail ? ` — ${item.detail}` : ''}</div>
      </div>`;
    }).join('');
    container.querySelectorAll('.ti-end').forEach(btn=>{
      btn.addEventListener('click', ()=>{
        const id = btn.closest('.tinker-item').dataset.id;
        writeTinkered(readTinkered().filter(i => i.id !== id));
        refreshTinkering();
      });
    });
  }

  function refreshTinkering(){
    renderSummary();
    renderList();
  }

  function addTinkered(){
    const nameEl = document.getElementById('tinkerObjectName');
    const typeEl = document.getElementById('tinkerPropertyType');
    const detailEl = document.getElementById('tinkerDetail');
    const { isArtificer, cap } = tinkerCap();
    const list = readTinkered();

    if(isArtificer && list.length >= cap){
      if(typeof showToast === 'function') showToast(`You can't maintain more than ${cap} tinkered properties at once (your proficiency bonus). End one first.`, 'warn');
      return;
    }
    if(!nameEl.value.trim()){
      if(typeof showToast === 'function') showToast('Name the object you\'re touching first.', 'warn');
      return;
    }
    list.push({
      id: `tinker_${Date.now()}_${Math.random().toString(36).slice(2,6)}`,
      objectName: nameEl.value.trim(),
      propertyType: typeEl.value,
      detail: detailEl.value.trim()
    });
    writeTinkered(list);
    nameEl.value = '';
    detailEl.value = '';
    refreshTinkering();
    if(typeof showToast === 'function') showToast('Object imbued.');
  }

  function openTinkering(){
    refreshTinkering();
    document.getElementById('tinkeringOverlay').style.display = 'flex';
  }
  function closeTinkering(){
    document.getElementById('tinkeringOverlay').style.display = 'none';
  }

  function init(){
    const openBtn = document.getElementById('btnOpenTinkering');
    const closeBtn = document.getElementById('btnCloseTinkering');
    const overlay = document.getElementById('tinkeringOverlay');
    const addBtn = document.getElementById('btnAddTinkered');
    if(openBtn) openBtn.addEventListener('click', openTinkering);
    if(closeBtn) closeBtn.addEventListener('click', closeTinkering);
    if(overlay) overlay.addEventListener('click', (e)=>{ if(e.target===overlay) closeTinkering(); });
    if(addBtn) addBtn.addEventListener('click', addTinkered);
    document.addEventListener('keydown', (e)=>{ if(e.key==='Escape') closeTinkering(); });

    // Load File doesn't fire input/change events on restored fields, so
    // re-render shortly after a file is chosen to pick up loaded objects.
    const fileInput = document.getElementById('fileInput');
    if(fileInput) fileInput.addEventListener('change', ()=> setTimeout(refreshTinkering, 400));
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();

// ============================================================================
// Show the Infusions / Tinkering buttons only for Artificer characters.
// Self-contained: doesn't touch js/app.js.
// ============================================================================

(function(){

  function isArtificer(){
    const el = document.querySelector('[name="classLevel"]');
    return !!(el && /artificer/i.test(el.value));
  }

  function updateVisibility(){
    const show = isArtificer();
    const infBtn = document.getElementById('btnOpenInfusions');
    const tinkBtn = document.getElementById('btnOpenTinkering');
    if(infBtn) infBtn.style.display = show ? '' : 'none';
    if(tinkBtn) tinkBtn.style.display = show ? '' : 'none';
  }

  function init(){
    updateVisibility();

    const confirmBtn = document.getElementById('btnConfirmChoices');
    if(confirmBtn) confirmBtn.addEventListener('click', updateVisibility);

    const newBtn = document.getElementById('btnNew');
    if(newBtn) newBtn.addEventListener('click', updateVisibility);

    const classLevelField = document.querySelector('[name="classLevel"]');
    if(classLevelField){
      classLevelField.addEventListener('input', updateVisibility);
      classLevelField.addEventListener('change', updateVisibility);
    }

    // Load File doesn't fire input/change events on restored fields.
    const fileInput = document.getElementById('fileInput');
    if(fileInput) fileInput.addEventListener('change', ()=> setTimeout(updateVisibility, 400));
  }

  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

})();
